// Processamento estruturado do Funil do Consultor Virtual — Oz Digital
const body = $input.first().json.body || $input.first().json;

const event = body.event || 'consultor_message';
if (event === 'ping_test') {
  return [{
    json: {
      ok: true,
      engine: 'n8n-vps-local',
      message: 'Webhook n8n Oz Digital ativo e respondendo corretamente!',
      receivedAt: new Date().toISOString()
    }
  }];
}

const message = (body.message || '').trim();
const lower = message.toLowerCase();
const step = body.step || 'objetivo';
const funnel = body.funnelData || {};

// Atualiza estado do funil a partir da mensagem recebida
const nextFunnel = {
  objetivo: funnel.objetivo || '',
  escopo: funnel.escopo || '',
  prazo: funnel.prazo || '',
  nome: funnel.nome || '',
  empresa: funnel.empresa || '',
  whatsapp: funnel.whatsapp || '',
  cidade: funnel.cidade || ''
};

// Detecta objetivo inicial
if (!nextFunnel.objetivo) {
  if (lower.includes('site') || lower.includes('wordpress') || lower.includes('landing')) {
    nextFunnel.objetivo = 'Site / Landing Page Profissional';
  } else if (lower.includes('sistema') || lower.includes('software') || lower.includes('gestor') || lower.includes('painel')) {
    nextFunnel.objetivo = 'Sistema Web Sob Medida';
  } else if (lower.includes('fluxo') || lower.includes('melhorar') || lower.includes('integr') || lower.includes('api') || lower.includes('automa')) {
    nextFunnel.objetivo = 'Melhorar Fluxo Existente & Integrações';
  } else if (lower.includes('explor') || lower.includes('360') || lower.includes('ecommerce') || lower.includes('loja') || lower.includes('hospedagem')) {
    nextFunnel.objetivo = 'Explorar Possibilidades / Solução 360°';
  } else if (step === 'objetivo' && message.length > 2) {
    nextFunnel.objetivo = message;
  }
}

// Se ja tem objetivo mas nao tem escopo, captura escopo
if (nextFunnel.objetivo && !nextFunnel.escopo && step === 'escopo' && message.length > 2) {
  nextFunnel.escopo = message;
}

// Extrai dados de contato se enviados por texto livre
const phoneMatch = message.match(/(?:\+?55\s?)?(?:\(?\s?[1-9]{2}\s?\)?\s?)?(?:9\s?\d{4}[-\s]?\d{4}|\d{4}[-\s]?\d{4})/);
if (phoneMatch && !nextFunnel.whatsapp) {
  nextFunnel.whatsapp = phoneMatch[0].trim();
}

// Define proxima etapa e resposta estruturada
let nextStep = step;
let reply = '';
let quickOptions = [];
let strategicSummary = null;

if (!nextFunnel.objetivo) {
  nextStep = 'objetivo';
  reply = 'Olá! Sou o **Consultor Virtual da Oz Digital** (rodando via n8n).\n\nPara montar um resumo estratégico para o seu negócio, **o que você precisa resolver hoje?**';
  quickOptions = [
    { label: 'Preciso de um site', value: 'Preciso de um site institucional profissional' },
    { label: 'Quero um sistema', value: 'Quero um sistema web sob medida' },
    { label: 'Melhorar fluxo existente', value: 'Quero melhorar um fluxo existente' },
    { label: 'Explorar possibilidades', value: 'Quero explorar possibilidades' }
  ];
} else if (!nextFunnel.escopo) {
  nextStep = 'escopo';
  reply = `Entendido: foco em **${nextFunnel.objetivo}**.\n\nQual é o **principal desafio atual** ou em quanto tempo você gostaria de colocar esse projeto no ar?`;
  quickOptions = [
    { label: 'Urgente (próximos 15 dias)', value: 'Preciso resolver com urgência nos próximos 15 dias' },
    { label: 'Planejamento (30 a 60 dias)', value: 'Estou planejando para os próximos 30 a 60 dias' },
    { label: 'Substituir planilhas / site lento', value: 'Quero substituir planilhas manuais ou um site lento' }
  ];
} else if (!nextFunnel.nome || !nextFunnel.whatsapp) {
  nextStep = 'contato';
  reply = 'Perfeito! Já estruturei o escopo técnico inicial.\n\nInforme seu **Nome**, **Empresa** e **WhatsApp com DDD** abaixo para gerar o **Resumo Estratégico do Projeto** e enviar para nossa equipe.';
} else {
  nextStep = 'resumo';
  const stackSugerida = nextFunnel.objetivo.toLowerCase().includes('sistema') || nextFunnel.objetivo.toLowerCase().includes('fluxo')
    ? 'React + Express + PostgreSQL + Docker (n8n)'
    : 'WordPress Otimizado + Cloud cPanel NVMe + SEO/GEO';

  const prazoEstimado = nextFunnel.objetivo.toLowerCase().includes('sistema')
    ? '15 a 30 dias úteis (entrega em sprints)'
    : '7 a 15 dias úteis';

  strategicSummary = {
    objetivo: nextFunnel.objetivo,
    escopo: nextFunnel.escopo,
    contato: `${nextFunnel.nome}${nextFunnel.empresa ? ` (${nextFunnel.empresa})` : ''}`,
    whatsapp: nextFunnel.whatsapp,
    arquiteturaSugerida: stackSugerida,
    prazoEstimado,
    proximosPassos: [
      '1. Entendimento detalhado das regras de negócio (Reunião de 20 min)',
      '2. Organização de fluxos e protótipo UX antes do código',
      '3. Desenvolvimento modular e homologação assistida'
    ]
  };

  reply = `Pronto, **${nextFunnel.nome}**! Seu **Resumo Estratégico** foi gerado pelo fluxo n8n.\n\nVocê pode enviar este diagnóstico diretamente para o WhatsApp da **Oz Digital** clicando no botão abaixo.`;
}

return [{
  json: {
    reply,
    nextStep,
    funnelData: nextFunnel,
    quickOptions,
    strategicSummary,
    engine: 'n8n-vps-local',
    processedAt: new Date().toISOString()
  }
}];
